function spreadGraphSvg(st, m) { const W = 250, H = 116, ox = 358, oy = 302, X = d => ox + d / 60 * 230, Y = n => oy + 96 - n / 64 * 88; const path = arr => arr.map((p, i) => `${i ? "L" : "M"}${X(p.day).toFixed(1)} ${Y(p.infected).toFixed(1)}`).join(" "); const cur = st.curve.concat([spreadCounts(st)]); return `<g><rect x="${ox - 18}" y="${oy - 8}" width="268" height="124" rx="14" fill="#fff" stroke="${CO}" stroke-width="3"/><path d="M${ox} ${oy + 96} H${ox + 232} M${ox} ${oy + 8} V${oy + 96}" stroke="${CO}" stroke-width="2"/>${st.ghosts.map(g => `<path d="${path(g)}" fill="none" stroke="#B8B0C6" stroke-width="2" opacity=".45"/>`).join("")}<path d="${path(cur)}" fill="none" stroke="#D2455F" stroke-width="4" stroke-linecap="round"/><circle cx="${X(st.day)}" cy="${Y(m.infected)}" r="5" fill="#D2455F" stroke="#fff" stroke-width="2"/><text x="${ox + 116}" y="${oy + 112}" text-anchor="middle" font-size="20" font-weight="900" fill="${CO}">days →</text><text x="${ox + 118}" y="${oy + 8}" text-anchor="middle" font-size="20" font-weight="950" fill="${CO}">infected curve</text></g>`; }
function spreadInfoHtml(disease) { const d = SPREAD_DISEASES[disease]; return `<div class="spread-card"><b>${d.name}</b>${spreadPathogenSvg(d.type)}<small>${d.type}; ${d.route}</small></div><div class="spread-card"><b>Virus</b>${spreadPathogenSvg("virus")}<small>protein coat + nucleic acid</small></div><div class="spread-card"><b>Bacterium</b>${spreadPathogenSvg("bacterium")}<small>cell wall + DNA loop</small></div><div class="spread-card"><b>Protist</b>${spreadPathogenSvg("protist")}<small>Plasmodium in red blood cell</small></div>`; }
function spreadPathogenSvg(type) { if (type === "bacterium") return `<svg viewBox="0 0 120 70" role="img" aria-label="rod-shaped bacterium"><rect x="24" y="18" width="72" height="34" rx="17" fill="#A7E0A7" stroke="${CO}" stroke-width="3"/><path d="M42 34 q20 -14 40 2" stroke="#2E7D32" stroke-width="3" fill="none"/><path d="M24 34 H8 M96 34 h16 M44 18 l-8 -12 M76 52 l8 12" stroke="#7DBB7D" stroke-width="3"/></svg>`; if (type === "protist") return `<svg viewBox="0 0 120 70" role="img" aria-label="Plasmodium protist inside red blood cell"><ellipse cx="60" cy="35" rx="43" ry="24" fill="#E9573F" stroke="${CO}" stroke-width="3"/><path d="M46 36 q18 -20 34 2 q-14 14 -34 -2" fill="#6C4AB6" stroke="#fff" stroke-width="2"/></svg>`; return `<svg viewBox="0 0 120 70" role="img" aria-label="virus with protein coat and nucleic acid"><g transform="translate(60 35)">${Array.from({ length: 12 }, (_, i) => { const a = i * Math.PI / 6, x = Math.cos(a) * 30, y = Math.sin(a) * 30; return `<line x1="${Math.cos(a) * 20}" y1="${Math.sin(a) * 20}" x2="${x}" y2="${y}" stroke="#6C4AB6" stroke-width="3"/><circle cx="${x}" cy="${y}" r="4" fill="#B497F2"/>`; }).join("")}<circle r="22" fill="#D7C6FF" stroke="${CO}" stroke-width="3"/><path d="M-10 -2 q10 -12 20 0 q-10 12 -20 0" stroke="#6C4AB6" stroke-width="3" fill="none"/></g></svg>`; }
function spreadChainHtml(m) { return [["🦠", "infected source", m.infected > 0], ["➡️", m.route, true], ["○", "susceptible hosts", m.susceptible > 0], ["💉", "immune barrier", m.vaccinatedCount > 20], ["📉", "curve flattened", m.flat]].map(([ic, t, on]) => `<div class="spread-step ${on ? "on" : ""}">${ic}<br>${t}</div>`).join(""); }

SIM_CH.smoke = { title: "Smoke Evidence Detective", mins: 15, story: "Run the machine, then connect each smoke chemical to the body damage it causes.", missions: [
  { ic: "🧪", name: "Machine test", tasks: [
    { type: "goal", ic: "⚪", do: "Choose <b>⚪ Control</b> and tap <b>▶ Run puffs</b>.", look: "Smoking machine", target: "Control run done", check: p => p.trial === "control" && p.runsControl >= 1, hold: .2, why: "The control checks that the apparatus does not turn cotton brown by itself." },
    { type: "read", ic: "📏", do: "Read the <b>control</b> results.", look: "Readout tiles", need: p => p.runsControl >= 1 && p.trial === "control", needTxt: "Run the control first.", fields: [["Tar on cotton", p => p.tar, 2, "%"], ["Temperature rise", p => p.tempRise, .8, "°C"]], why: "With no cigarette, tar and heating stay near zero." },
    { type: "goal", ic: "🚬", do: "Now choose <b>🚬 Cigarette</b> and run the same puffs.", look: "U-tube cotton + indicator", target: "Cigarette run done", check: p => p.trial === "cig" && p.runsCig >= 1 && p.puffs >= 5, hold: .2, why: "A fair comparison uses the same number of puffs." },
    { type: "read", ic: "🟤", do: "Read the <b>cigarette</b> tar and indicator colour.", look: "Readout tiles", need: p => p.trial === "cig" && p.runsCig >= 1, needTxt: "Cigarette run completed.", fields: [["Tar on cotton", p => p.tar, 5, "%"]], why: "Tar stains the cotton brown; acidic gases/CO₂ turn hydrogencarbonate indicator yellow." }] },
  { ic: "🫁", name: "Airways", tasks: [
    { type: "goal", ic: "🚬", do: "Use <b>🚬 Heavy</b> or sliders to make cilia work below 35%.", look: "Ciliated epithelium", target: "Cilia < 35%", check: p => p.cilia < 35, hold: .3, meter: p => ({ v: p.cilia, min: 0, max: 100, lo: 0, hi: 35, unit: "%", label: "Cilia working" }), why: "Tar paralyses and destroys cilia, so mucus is not swept away." },
    { type: "pick", ic: "💧", do: "Why does a smoker get more coughs and bronchitis?", opts: ["Mucus with trapped germs builds up when cilia fail", "Cilia make extra oxygen", "Carbon monoxide kills all germs", "Nicotine digests mucus"], miss: ["", "Cilia move mucus; they do not make oxygen.", "CO reduces oxygen transport; it does not sterilise airways.", "Nicotine is addictive and affects blood vessels."], why: "Mucus accumulation irritates airways and helps pathogens remain, causing cough and infections." },
    { type: "goal", ic: "🫧", do: "Make <b>alveolar area</b> fall below 65%.", look: "Alveoli panel", target: "Alveolar surface area < 65%", check: p => p.alveolar < 65, hold: .3, meter: p => ({ v: p.alveolar, min: 0, max: 100, lo: 0, hi: 65, unit: "%", label: "Alveolar area" }), why: "In emphysema, alveolar walls break down, leaving less surface area for gas exchange." }] },
  { ic: "🩸", name: "Blood + recovery", tasks: [
    { type: "goal", ic: "CO", do: "Set <b>cigarettes/day</b> above 20 and make O₂ carried below 75%.", look: "O₂ carried tile", target: "O₂ carried < 75%", check: p => p.cigs > 20 && p.o2 < 75, hold: .3, meter: p => ({ v: p.o2, min: 50, max: 100, lo: 50, hi: 75, unit: "%", label: "O₂ carried" }), why: "Carbon monoxide forms carboxyhaemoglobin, so less haemoglobin carries oxygen." },
    { type: "goal", ic: "🌱", do: "Slide <b>years since quitting</b> to 10 or more.", look: "Exposure controls", target: "Quit ≥ 10 years", check: p => p.quit >= 10, hold: .2, why: "Risk falls after quitting because exposure stops, though some damage is slow or incomplete to recover." },
    { type: "read", ic: "⚠️", do: "Read the <b>lung cancer risk</b> after quitting.", look: "Risk tile", need: p => p.quit >= 10, needTxt: "Set quitting to 10 years or more.", fields: [["Lung cancer risk", p => p.cancerRisk, .8, "×"]], why: "Cancer risk falls gradually over years, but remains above never-smoker risk for some time." }] },
  { ic: "✍️", name: "Explain", tasks: [
    { type: "order", ic: "🔢", do: "Put the <b>smoker's cough</b> chain in order.", items: ["Tar enters the airway", "Cilia are paralysed or destroyed", "Mucus is not swept away", "Mucus and germs accumulate", "Cough, bronchitis and infections become more likely"], why: "This is the airway cause→effect chain." },
    { type: "fill", ic: "✍️", do: "Complete the blood sentence.", text: "Carbon monoxide combines with {haemoglobin|mucus|cilia} to form carboxyhaemoglobin, so less {oxygen|tar|nicotine} is carried.", why: "CO competes with oxygen for haemoglobin." },
    { type: "pick", ic: "⚠️", do: "Which chemical group is most linked with lung cancer?", opts: ["Tar contains carcinogens that can cause mutations", "Carbon dioxide makes cells divide normally", "Nicotine is oxygen", "Water vapour is a carcinogen"], miss: ["", "CO₂ is not the main carcinogen in tobacco smoke.", "Nicotine is addictive, not oxygen.", "Water vapour is present in breath, not a tobacco carcinogen."], why: "Carcinogens in tar can damage DNA and lead to uncontrolled cell division." }] }
] };

SIM_CH.heartrisk = { title: "Coronary Artery Detective", mins: 15, story: "Compare lifestyles, read the lumen and flow, then explain coronary heart disease.", missions: [
  { ic: "🥗", name: "Compare", tasks: [
    { type: "goal", ic: "🥗", do: "Tap <b>🥗 Healthy habits</b>.", look: "Preset buttons", target: "Healthy preset tried", check: p => p.triedHealthy >= 1 && p.flow > 70, hold: .2, why: "Modifiable factors can keep plaque build-up low." },
    { type: "read", ic: "📏", do: "Read the healthy <b>lumen left</b> and <b>flow</b>.", look: "Readout tiles", need: p => p.triedHealthy >= 1, needTxt: "Healthy preset tried.", fields: [["Lumen left", p => p.lumen, 8, "%"], ["Blood flow", p => p.flow, 12, "%"]], why: "A wide lumen keeps resistance low, so flow remains high." },
    { type: "goal", ic: "🍟", do: "Tap <b>🍟 High risk</b>.", look: "Artery cross-section", target: "High risk preset tried", check: p => p.triedRisk >= 1 && p.narrowing > 60, hold: .2, meter: p => ({ v: p.narrowing, min: 0, max: 95, lo: 60, hi: 95, unit: "%", label: "Narrowing" }), why: "High-fat/salt diet, smoking, obesity, high blood pressure and low exercise raise risk." },
    { type: "read", ic: "🩸", do: "Read the high-risk <b>narrowing</b> and <b>flow</b>.", look: "Readout tiles", need: p => p.triedRisk >= 1 && p.narrowing > 60, needTxt: "High risk with plaque present.", fields: [["Narrowing", p => p.narrowing, 8, "%"], ["Blood flow", p => p.flow, 10, "%"]], why: "Flow falls steeply as the lumen radius gets smaller." }] },
  { ic: "🧈", name: "Plaque chain", tasks: [
    { type: "goal", ic: "📅", do: "Move <b>years</b> above 25 with high-risk settings.", look: "Timeline slider", target: "Long exposure", check: p => p.years > 25 && p.narrowing > 60, hold: .3, why: "Atherosclerosis builds up slowly over years." },
    { type: "pick", ic: "💢", do: "Why can narrowed coronary arteries cause angina?", opts: ["Less blood flow brings less oxygen to heart muscle", "More mucus blocks the trachea", "The aorta becomes a vein", "White blood cells digest the heart"], miss: ["", "That is a smoking airway problem, not angina.", "The vessel does not change into a vein.", "White blood cells do not normally digest heart muscle."], why: "Heart muscle respires; low oxygen causes chest pain called angina." },
    { type: "goal", ic: "🩸", do: "Turn on <b>⚠️ Plaque rupture → clot</b>.", look: "Clot checkbox + long-section", target: "Clot blocks artery", check: p => p.clot && p.flow === 0, hold: .2, why: "A ruptured plaque can form a clot that blocks the coronary artery." }] },
  { ic: "🎛️", name: "Risk factors", tasks: [
    { type: "goal", ic: "🏃", do: "Set a lower-risk lifestyle: balanced diet, no smoking, regular exercise.", look: "Risk controls", target: "Three modifiable risks improved", check: p => p.diet === 0 && p.smoke === 0 && p.exercise === 2, hold: .2, why: "Diet, smoking and exercise are modifiable risk factors." },
    { type: "goal", ic: "🧬", do: "Switch on <b>🧬 family genes</b> and set age above 55.", look: "Genes + age controls", target: "Non-modifiable risks shown", check: p => p.genes && p.age > 55, hold: .2, why: "Age and inherited genes affect risk but cannot be changed." },
    { type: "pick", ic: "🧭", do: "Which list contains only <b>modifiable</b> risk factors?", opts: ["Smoking, diet, exercise, body mass and blood pressure", "Age, genes and family history", "Genes, age and smoking", "Coronary artery and left ventricle"], miss: ["", "Those cannot be changed.", "Smoking is modifiable, but genes and age are not.", "Those are body parts, not risk factors."], why: "Modifiable means a person can change it by behaviour or treatment." }] },
  { ic: "🩺", name: "Explain + treat", tasks: [
    { type: "order", ic: "🔢", do: "Put the <b>heart attack</b> chain in order.", items: ["Fatty plaque builds up in a coronary artery", "The lumen narrows and blood flow falls", "A plaque ruptures", "A blood clot blocks the artery", "Heart muscle lacks oxygen and dies"], why: "This is coronary heart disease leading to a heart attack." },
    { type: "fill", ic: "✍️", do: "Complete the prevention sentence.", text: "Balanced diet, regular {exercise|smoking|genes} and no {smoking|ageing|oxygen} lower coronary heart disease risk.", why: "Lifestyle changes lower modifiable risk factors." },
    { type: "pick", ic: "🧷", do: "What does a <b>stent</b> do?", opts: ["Holds a narrowed artery open to improve blood flow", "Makes nicotine less addictive", "Turns veins into capillaries", "Kills viruses in the blood"], miss: ["", "That is not a stent's job.", "A stent is placed in an artery.", "Stents are not antibiotics or antivirals."], why: "A stent is a small tube that widens the artery lumen; bypass surgery makes an alternative route." }] }
] };

SIM_CH.spread = { title: "Outbreak Controller", mins: 15, story: "Run a seeded outbreak, flatten the curve, and match each disease to its transmission route.", missions: [
  { ic: "🤧", name: "Start flu", tasks: [
    { type: "goal", ic: "🤧", do: "Choose <b>🤧 Influenza</b> and press <b>▶ Run</b> past day 5.", look: "Estate dots + curve", target: "Flu day > 5", check: p => p.disease === "flu" && p.running && p.day > 5, hold: .2, meter: p => ({ v: p.day, min: 0, max: 60, lo: 5, hi: 60, unit: " d", label: "Day" }), why: "Flu spreads by droplets from infected people to susceptible people." },
    { type: "read", ic: "📈", do: "Read the current <b>peak infected</b> and <b>total infected</b>.", look: "Readout tiles", need: p => p.disease === "flu" && p.day > 5, needTxt: "Flu run past day 5.", fields: [["Peak infected", p => p.peak, 3, "people"], ["Total infected", p => p.total, 4, "people"]], why: "Peak shows health-service pressure; total shows how many caught the disease." },
    { type: "pick", ic: "➡️", do: "What is the transmission route for influenza?", opts: ["Airborne droplets", "Aedes mosquito vector", "Contaminated water only", "Genes from parents"], miss: ["", "That fits dengue fever.", "That fits cholera better.", "Genes do not make a communicable outbreak."], why: "Influenza viruses leave in droplets when people cough, sneeze or talk." }] },
  { ic: "📉", name: "Flatten", tasks: [
    { type: "goal", ic: "🛡️", do: "Tap <b>🛡️ Flatten</b>, then run to day 30.", look: "Prevention sliders + curve", target: "Prevention run day ≥ 30", check: p => p.vaccination >= 70 && p.routeControl >= 70 && p.isolation >= 50 && p.day >= 30, hold: .2, meter: p => ({ v: p.day, min: 0, max: 60, lo: 30, hi: 60, unit: " d", label: "Day" }), why: "Layered prevention reduces transmission and flattens the curve." },
    { type: "read", ic: "🔢", do: "Read the flattened <b>peak</b>.", look: "Peak tile", need: p => p.day >= 30 && p.vaccination >= 70, needTxt: "Run the flattened outbreak to day 30.", fields: [["Peak infected", p => p.peak, 3, "people"]], why: "A lower peak means fewer people are ill at the same time." },
    { type: "goal", ic: "💉", do: "Set vaccination at or above the <b>herd mark</b> for flu.", look: "Vaccination slider + herd mark tile", target: "Vaccination ≥ herd mark", check: p => p.disease === "flu" && p.vaccination >= p.threshold, hold: .2, why: "Herd immunity makes each infection less likely to find a susceptible host." }] },
  { ic: "🧭", name: "Routes", tasks: [
    { type: "goal", ic: "🚰", do: "Choose <b>🚰 Cholera</b> and raise route control above 70%.", look: "Disease + route control", target: "Cholera water control", check: p => p.disease === "cholera" && p.routeControl >= 70, hold: .2, why: "Clean water, boiling water and cooking food well reduce water/food transmission." },
    { type: "goal", ic: "🦟", do: "Choose <b>🦟 Dengue</b> and raise route control above 70%.", look: "Mosquito route control", target: "Dengue vector control", check: p => p.disease === "dengue" && p.routeControl >= 70, hold: .2, why: "Removing stagnant water reduces Aedes mosquito breeding sites." },
    { type: "pick", ic: "💊", do: "A classmate wants antibiotics for dengue. Best answer?", opts: ["No: dengue is viral, so antibiotics do not work", "Yes: antibiotics kill all viruses", "Yes: dengue is a bacterium", "No prevention is possible"], miss: ["", "Antibiotics act against bacteria, not viruses.", "The pathogen card labels dengue as a virus.", "Vector control can reduce spread."], why: "Match treatment/prevention to the pathogen and route." }] },
  { ic: "✍️", name: "Explain", tasks: [
    { type: "order", ic: "🔢", do: "Put the outbreak states in order.", items: ["Susceptible person is exposed", "Pathogen is transmitted by its route", "Person becomes infected", "Person recovers and becomes immune", "More immune people reduce later spread"], why: "The model uses susceptible → infected → recovered/immune." },
    { type: "fill", ic: "✍️", do: "Complete the herd immunity sentence.", text: "When many people are {immune|infected|susceptible}, a pathogen has fewer {susceptible hosts|mosquito wings|antibiotics} to infect.", why: "Vaccinated/immune people block transmission chains." },
    { type: "pick", ic: "🔬", do: "Which pathogen type is <b>cholera</b>?", opts: ["Bacterium", "Virus", "Protist", "Fungus"], miss: ["", "Flu and dengue are viruses here.", "Malaria is a protist disease example.", "Athlete's foot is fungal."], why: "Cholera is caused by a bacterium and spreads in contaminated water/food." }] }
] };
